import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Form Proposal: RelationalDatabase","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/relational-database.md","filePath":"proposals/relational-database.md"}'),n={name:"proposals/relational-database.md"};function o(s,a,l,d,c,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="form-proposal-relationaldatabase" tabindex="-1">Form Proposal: RelationalDatabase <a class="header-anchor" href="#form-proposal-relationaldatabase" aria-label="Permalink to &quot;Form Proposal: RelationalDatabase&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>The candidate Form describes a relational database lifecycle and a query Interface, including engine compatibility, optional digest-bound schema material, lifecycle identity, and observable query capability. Credentials, storage size, size class, topology, replica implementation, network placement, backup machinery, capacity, and price stay with the host.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>Engine/version and schema bytes can be interpreted consistently by a managed database, an operator-managed database, or a self-hosted engine. Storage size, size class, high availability, backup tier, region, and endpoint compatibility are excluded because their guarantees and lifecycle differ by host offering.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Engine-family changes may require export and replacement. Delete and migration can destroy durable data and therefore require explicit retention/recovery evidence. Import binds an exact existing database. Credentials are host-owned Interface bindings and never portable output or provider state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Resource/Storage/Link, CIMI System/Volume, TOSCA Database/DBMS nodes, Kubernetes database operators, Crossplane managed databases, and Terraform RDS/Cloud SQL/D1/PostgreSQL resources are applicable. The gap is a small relational service intent with a portable query capability but no standardized credential, topology, or engine implementation.</p>',10)])])}const h=e(n,[["render",o]]);export{u as __pageData,h as default};
